// Code as Action (CodeAct).
// The agent's action is one structured program (loops, conditionals,
// variables) that orchestrates three tools over 500 orders in a single turn.
// A tiny interpreter walks the fixed op structure; nothing is eval'd. The 500
// intermediate records stay in the runtime, and only the final total returns.

use std::collections::HashMap;

const TODAY: f64 = 15.0;
const RATES: [f64; 4] = [0.20, 0.08, 0.10, 0.15];

// A runtime value: a scalar, one record, or a list of records.
#[derive(Clone)]
enum Value {
    Num(f64),
    Row(HashMap<String, f64>),
    Rows(Vec<HashMap<String, f64>>),
}

enum BodyOp {
    Call { result: String, tool: String, args: Vec<String> },
    Guard { reference: String, less_than: f64, into: String, add: Vec<String> },
}

enum Op {
    Load { result: String, tool: String },
    Foreach { item_var: String, list_var: String, body: Vec<BodyOp> },
    Return { reference: String },
}

struct Stats {
    tool_calls: usize,
    rows: usize,
    overdue: usize,
    records: usize,
}

fn num(v: &Value) -> f64 {
    if let Value::Num(n) = v { *n } else { 0.0 }
}

fn row(pairs: &[(&str, f64)]) -> HashMap<String, f64> {
    pairs.iter().map(|(k, v)| (k.to_string(), *v)).collect()
}

// Simulated tools. Each returns canned-but-deterministic data.
fn read_csv() -> Vec<HashMap<String, f64>> {
    (0..500i64)
        .map(|i| row(&[
            ("id", i as f64),
            ("customer_id", (1 + (i % 20)) as f64),
            ("amount", (50 + ((i * 37) % 950)) as f64),
            ("due_day", (1 + ((i * 7) % 28)) as f64),
        ]))
        .collect()
}

fn get_customer(cid: f64) -> HashMap<String, f64> {
    row(&[("id", cid), ("region", (cid as i64 % 4) as f64)])
}

fn compute_tax(amount: f64, region: f64) -> f64 {
    (amount * RATES[region as usize] * 100.0).round() / 100.0
}

fn call_tool(name: &str, args: &[Value]) -> Value {
    match name {
        "read_csv" => Value::Rows(read_csv()),
        "get_customer" => Value::Row(get_customer(num(&args[0]))),
        "compute_tax" => Value::Num(compute_tax(num(&args[0]), num(&args[1]))),
        _ => Value::Num(0.0),
    }
}

// Resolve a reference like "r.amount" or a plain var like "tax" from runtime.
fn resolve(rt: &HashMap<String, Value>, reference: &str) -> Value {
    if let Some(dot) = reference.find('.') {
        if let Value::Row(m) = &rt[&reference[..dot]] {
            return Value::Num(m[&reference[dot + 1..]]);
        }
        return Value::Num(0.0);
    }
    rt[reference].clone()
}

// The interpreter: one turn executes the whole program, tools included.
fn run_program(program: &[Op]) -> (f64, Stats) {
    let mut rt: HashMap<String, Value> = HashMap::new();
    rt.insert("total".to_string(), Value::Num(0.0));
    let mut stats = Stats { tool_calls: 0, rows: 0, overdue: 0, records: 0 };
    let mut returned = 0.0;

    for op in program {
        match op {
            Op::Load { result, tool } => {
                rt.insert(result.clone(), call_tool(tool, &[]));
                stats.tool_calls += 1;
                if let Value::Rows(r) = &rt[result] {
                    stats.rows = r.len();
                }
            }
            Op::Foreach { item_var, list_var, body } => {
                let rows = match &rt[list_var] {
                    Value::Rows(r) => r.clone(),
                    _ => Vec::new(),
                };
                for r in rows {
                    rt.insert(item_var.clone(), Value::Row(r));
                    for step in body {
                        match step {
                            BodyOp::Call { result, tool, args } => {
                                let resolved: Vec<Value> = args.iter().map(|a| resolve(&rt, a)).collect();
                                rt.insert(result.clone(), call_tool(tool, &resolved));
                                stats.tool_calls += 1;
                                if tool == "get_customer" {
                                    stats.records += 1; // stays in runtime
                                }
                            }
                            BodyOp::Guard { reference, less_than, into, add } => {
                                if num(&resolve(&rt, reference)) < *less_than {
                                    let delta: f64 = add.iter().map(|a| num(&resolve(&rt, a))).sum();
                                    let current = num(&rt[into]);
                                    rt.insert(into.clone(), Value::Num(current + delta));
                                    stats.overdue += 1;
                                }
                            }
                        }
                    }
                }
            }
            Op::Return { reference } => returned = num(&rt[reference]),
        }
    }
    (returned, stats)
}

fn call(result: &str, tool: &str, args: &[&str]) -> BodyOp {
    BodyOp::Call { result: result.to_string(), tool: tool.to_string(), args: args.iter().map(|s| s.to_string()).collect() }
}

fn main() {
    println!("Code as Action, one program orchestrates 3 tools over 500 orders\n");

    // The agent's single code action, expressed as a fixed op structure.
    let program = vec![
        Op::Load { result: "rows".to_string(), tool: "read_csv".to_string() },
        Op::Foreach {
            item_var: "r".to_string(),
            list_var: "rows".to_string(),
            body: vec![
                call("c", "get_customer", &["r.customer_id"]),
                call("tax", "compute_tax", &["r.amount", "c.region"]),
                BodyOp::Guard { reference: "r.due_day".to_string(), less_than: TODAY, into: "total".to_string(), add: vec!["r.amount".to_string(), "tax".to_string()] },
            ],
        },
        Op::Return { reference: "total".to_string() },
    ];

    for line in [
        "Code action (interpreted, never eval'd):",
        "  rows = read_csv(\"orders.csv\")",
        "  total = 0",
        "  for r in rows:",
        "      c = get_customer(r.customer_id)",
        "      tax = compute_tax(r.amount, c.region)",
        "      if r.due_day < 15:",
        "          total += r.amount + tax",
        "  return total\n",
    ] {
        println!("{}", line);
    }

    let (total, stats) = run_program(&program);

    println!("Execution (single turn):");
    println!("  rows processed        : {}", stats.rows);
    println!("  tool calls made       : {} (read_csv + 2 per row)", stats.tool_calls);
    println!("  customer records built: {} (kept in runtime, never returned)", stats.records);
    println!("  overdue orders        : {}", stats.overdue);
    println!("  total returned        : {:.2}\n", total);

    let json_round_trips = 1 + stats.rows * 2;
    println!("Context traffic:");
    println!("  CodeAct: 1 value returned to the model");
    println!("  JSON-call way: {} tool results would round-trip through context", json_round_trips);
    println!("The intermediate records never entered the context window.");
}

