// Code as Action (CodeAct).
// The agent's action is one structured program (loops, conditionals,
// variables) that orchestrates three tools over 500 orders in a single turn.
// A tiny interpreter walks the fixed op structure; nothing is eval'd. The 500
// intermediate records stay in the runtime, and only the final total returns.

interface LoadOp { kind: 'load'; result: string; tool: string; arg: string; }
interface CallOp { kind: 'call'; result: string; tool: string; args: string[]; }
interface GuardOp { kind: 'guard'; ref: string; lessThan: number; into: string; add: string[]; }
interface ForeachOp { kind: 'foreach'; itemVar: string; listVar: string; body: (CallOp | GuardOp)[]; }
interface ReturnOp { kind: 'return'; ref: string; }
type Op = LoadOp | ForeachOp | ReturnOp;

const TODAY = 15;
const RATES: Record<string, number> = { eu: 0.2, us: 0.08, apac: 0.1, latam: 0.15 };

// Simulated tools. Each returns canned-but-deterministic data.
function readCsv(): Record<string, number>[] {
  const rows: Record<string, number>[] = [];
  for (let i = 0; i < 500; i++) {
    rows.push({ id: i, customer_id: 1 + (i % 20), amount: 50 + ((i * 37) % 950), due_day: 1 + ((i * 7) % 28) });
  }
  return rows;
}
function getCustomer(id: number): Record<string, any> {
  const regions = ['eu', 'us', 'apac', 'latam'];
  return { id, region: regions[id % regions.length] };
}
function computeTax(amount: number, region: string): number {
  return Math.round(amount * RATES[region] * 100) / 100;
}

const TOOLS: Record<string, (args: any[]) => any> = {
  read_csv: () => readCsv(),
  get_customer: args => getCustomer(args[0]),
  compute_tax: args => computeTax(args[0], args[1]),
};

// Resolve a reference like "r.amount" or a plain var like "tax" from runtime.
function resolve(runtime: Record<string, any>, ref: string): any {
  if (ref.includes('.')) {
    const parts = ref.split('.');
    return runtime[parts[0]][parts[1]];
  }
  return runtime[ref];
}

interface Stats { toolCalls: number; rows: number; overdue: number; records: number; }

// The interpreter: one turn executes the whole program, tools included.
function runProgram(program: Op[]): { total: number; stats: Stats } {
  const runtime: Record<string, any> = { total: 0 };
  const stats: Stats = { toolCalls: 0, rows: 0, overdue: 0, records: 0 };
  let returned = 0;
  for (const op of program) {
    if (op.kind === 'load') {
      runtime[op.result] = TOOLS[op.tool]([op.arg]);
      stats.toolCalls++;
      stats.rows = runtime[op.result].length;
    } else if (op.kind === 'foreach') {
      for (const item of runtime[op.listVar]) {
        runtime[op.itemVar] = item;
        for (const step of op.body) {
          if (step.kind === 'call') {
            const args = step.args.map(a => resolve(runtime, a));
            runtime[step.result] = TOOLS[step.tool](args);
            stats.toolCalls++;
            if (step.tool === 'get_customer') stats.records++; // stays in runtime
          } else {
            if (resolve(runtime, step.ref) < step.lessThan) {
              const delta = step.add.reduce((sum, a) => sum + resolve(runtime, a), 0);
              runtime[step.into] = runtime[step.into] + delta;
              stats.overdue++;
            }
          }
        }
      }
    } else if (op.kind === 'return') {
      returned = runtime[op.ref];
    }
  }
  return { total: returned, stats };
}

function main() {
  console.log('Code as Action, one program orchestrates 3 tools over 500 orders\n');

  // The agent's single code action, expressed as a fixed op structure.
  const program: Op[] = [
    { kind: 'load', result: 'rows', tool: 'read_csv', arg: 'orders.csv' },
    {
      kind: 'foreach',
      itemVar: 'r',
      listVar: 'rows',
      body: [
        { kind: 'call', result: 'c', tool: 'get_customer', args: ['r.customer_id'] },
        { kind: 'call', result: 'tax', tool: 'compute_tax', args: ['r.amount', 'c.region'] },
        { kind: 'guard', ref: 'r.due_day', lessThan: TODAY, into: 'total', add: ['r.amount', 'tax'] },
      ],
    },
    { kind: 'return', ref: 'total' },
  ];

  console.log('Code action (interpreted, never eval\'d):');
  console.log('  rows = read_csv("orders.csv")');
  console.log('  total = 0');
  console.log('  for r in rows:');
  console.log('      c = get_customer(r.customer_id)');
  console.log('      tax = compute_tax(r.amount, c.region)');
  console.log(`      if r.due_day < ${TODAY}:`);
  console.log('          total += r.amount + tax');
  console.log('  return total\n');

  const { total, stats } = runProgram(program);

  console.log('Execution (single turn):');
  console.log(`  rows processed        : ${stats.rows}`);
  console.log(`  tool calls made       : ${stats.toolCalls} (read_csv + 2 per row)`);
  console.log(`  customer records built: ${stats.records} (kept in runtime, never returned)`);
  console.log(`  overdue orders        : ${stats.overdue}`);
  console.log(`  total returned        : ${total.toFixed(2)}\n`);

  const jsonRoundTrips = 1 + stats.rows * 2;
  console.log('Context traffic:');
  console.log(`  CodeAct: 1 value returned to the model`);
  console.log(`  JSON-call way: ${jsonRoundTrips} tool results would round-trip through context`);
  console.log('The intermediate records never entered the context window.');
}

main();
